/bin/bash -lc "cat <<EOF > /workspace/openai_client.py
import json
import urllib.request
import urllib.error
import os

def send_prompt(api_key, model, prompt, api_base=\"https://api.openai.com/v1\"):
    \"\"\"
    Sends a text prompt to OpenAI's Chat Completions API using only the standard library.
    \"\"\"
    url = f\"{api_base}/chat/completions\"
    headers = {
        \"Content-Type\": \"application/json\",
        \"Authorization\": f\"Bearer {api_key}\"
    }
    data = {
        \"model\": model,
        \"messages\": [{\"role\": \"user\", \"content\": prompt}]
    }

    req = urllib.request.Request(
        url, 
        data=json.dumps(data).encode(\"utf-8\"), 
        headers=headers, 
        method=\"POST\"
    )

    try:
        with urllib.request.urlopen(req) as response:
            return json.loads(response.read().decode(\"utf-8\"))
    except urllib.error.HTTPError as e:
        return {\"error\": e.read().decode(\"utf-8\")}
    except Exception as e:
        return {\"error\": str(e)}

if __name__ == \"__main__\":
    # Example usage:
    # key = os.getenv(\"OPENAI_API_KEY\")
    # print(send_prompt(key, \"gpt-4o\", \"Hello, how are you?\"))
    pass
EOF
